import { useState, useEffect } from 'react';
import { useParams } from 'react-router-dom';
import './Profile.css';

function Profile() {
  const { userId } = useParams();
  const [profile, setProfile] = useState(null);
  const [posts, setPosts] = useState([]);
  const [friendRequests, setFriendRequests] = useState([]);
  const [isLoading, setIsLoading] = useState(true);

  useEffect(() => {
    const userLogatId = 4; // ID-ul utilizatorului logat

    const fetchProfile = async () => {
      try {
        const res = await fetch(`http://127.0.0.1:8000/profile/${userId}`);
        const data = await res.json();
        const isCurrentUser = parseInt(data.id_user) === parseInt(userLogatId);

        setProfile({
          id: data.id_user,
          name: `${data.nume} ${data.prenume}`,
          username: data.email.split('@')[0],
          bio: data.bio,
          avatar: null,
          isCurrentUser,
        });
      } catch (err) {
        console.error(err);
      } finally {
        setIsLoading(false);
      }
    };

    const fetchPosts = async () => {
      const res = await fetch(`http://127.0.0.1:8000/profile/${userId}/posts`);
      const data = await res.json();
      setPosts(data);
    };

    const fetchFriendRequests = async () => {
      const res = await fetch(`http://127.0.0.1:8000/profile/${userId}/friend-requests`);
      const data = await res.json();
      setFriendRequests(data);
    };

    fetchProfile();
    fetchPosts();
    fetchFriendRequests();
  }, [userId]);

  if (isLoading) return <div className="loading">Loading...</div>;
  if (!profile) return <div className="error">Profile not found</div>;

  return (
    <div className="profile-container">
      <div className="profile-header">
        <div className="profile-avatar">
          <img src={profile.avatar || '/default-avatar.jpg'} alt={profile.name} />
        </div>

        <div className="profile-info">
          <h1>{profile.name}</h1>
          <p className="username">@{profile.username}</p>
          <p className="bio">{profile.bio || 'No bio yet'}</p>

          <div className="profile-stats">
            <div><strong>{posts.length}</strong><span>Posts</span></div>
            <div><strong>{friendRequests.length}</strong><span>Friend Requests</span></div>
            <div><strong>0</strong><span>Friends</span></div>
          </div>
        </div>
      </div>

      <div className="profile-content">
        {profile.isCurrentUser && friendRequests.length > 0 && (
          <div className="friend-requests">
            <h3>Friend Requests</h3>
            <ul>
              {friendRequests.map(req => (
                <li key={req.id}>{req.from_user.name}</li>
              ))}
            </ul>
          </div>
        )}

        <div className="posts-grid">
          {posts.length > 0 ? (
            posts.map(post => (
              <div key={post.id} className="post-thumbnail">
                <img src={post.image} alt="User post" />
                <div className="post-overlay">
                  <span>❤️ {post.likes}</span>
                  <span>💬 {post.comments}</span>
                </div>
              </div>
            ))
          ) : (
            <p>No posts yet</p>
          )}
        </div>
      </div>
    </div>
  );
}

export default Profile;
